const b = $json.body || {};
const comment = String(b.comment || '').trim();
const chips = Array.isArray(b.chips) ? b.chips.filter(Boolean).slice(0, 10) : [];
if (!comment && !chips.length) throw new Error('потрібна правка');
const rules = Array.isArray(b.rules) ? b.rules.filter(Boolean).slice(0, 12) : [];
const user = [
  (b.format === 'reel' ? 'Рілс' : 'Відео') + ' «' + (b.name || '') + '» · ' + (b.platform === 'telegram' ? 'Telegram-канал' : 'Instagram'),
  'Місце: ' + (b.place || '—') + (b.hotel ? ' · готель ' + b.hotel : ''),
  'Текст на екрані: ' + (b.screen || '—'),
  b.voice ? 'Голос Іри (субтитри): ' + b.voice : '',
  '',
  'Поточний підпис:',
  String(b.caption || '').trim() || '(порожньо — напиши новий)',
  '',
  'ПРАВКА ІРИ: ' + (comment || chips.join(' · ')),  // чіпи апка вже дописує в текст правки
  rules.length ? '\nПРАВИЛА ІРИ З ЇЇ ПОПЕРЕДНІХ ПРАВОК (дотримуйся; її поточна правка має пріоритет):\n' + rules.map(r => '— ' + r).join('\n') : '',
].filter(s => s !== '').join('\n');
return [{ json: { body: {
  model: 'gpt-4.1',
  temperature: 0.6,
  response_format: { type: 'json_object' },
  messages: [ { role: 'system', content: "Ти — контент-агентка Іри (TravelLab: кураторка люкс-подорожей, острівні family-резорти, Мальдіви).\nПереписуєш підпис (caption) — текст ПІД коротким вертикальним відео — за правкою Іри.\nТон Іри (PRMPT-011): жива проста мова, звертання на «ви», ОДНА думка на відео; не вигадуй, що Іра там була\n(без «я була», «з власного досвіду», «ми відпочивали»); без перебільшень («найкращий», «єдиний», «мало де», «рай»);\nне називай готель, якого нема в даних. Кожне речення — граматично правильна природна українська.\n\nПравила підпису: 80–600 знаків, 2–4 короткі абзаци; перший рядок — гачок; далі 1–2 живі деталі, що видно в кадрах, і що це дає людині;\nзвертання на «ви»; без хештегів, цін, знижок, CTA, питань-опитувань, «посилання в біо»; емодзі — максимум 2 або жодного;\nне повторюй дослівно текст з екрана.\n\nЯк працювати з правкою:\n- зроби саме те, що просить Іра; її правка важливіша за правила вище (крім вигадок — нічого не вигадуй);\n- те, про що вона не просила, лишай як було — не переписуй підпис з нуля без потреби;\n- факти — лише з її правки, поточного підпису, тексту на екрані й голосу.\n\nПоверни СТРОГО JSON: {\"caption\": \"новий підпис\"}." }, { role: 'user', content: user } ],
} } }];

let o = {};
try { o = JSON.parse($json.choices[0].message.content); } catch (e) { o = {}; }
const caption = String(o.caption || '')
  .replace(/(^|\s)#[\w\u0400-\u04FF]+/g, '$1')
  .replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim().slice(0, 2200);
return [{ json: { caption } }];
